function Provider({children}){const[me,setMe]=useState(null),[boot,setBoot]=useState(true),[catalog,setCatalog]=useState({categories:[],services:[]}),[toast,setToast]=useState('');const reloadVersion=useRef(0);async function reload(){const version=++reloadVersion.current;try{const next=await api('/me');if(version===reloadVersion.current)setMe(next)}catch{if(version===reloadVersion.current)setMe(null)}}useEffect(()=>{api('/services').then(setCatalog).catch(e=>setToast(e.message));reload().finally(()=>setBoot(false));const tick=setInterval(reload,10000);return()=>clearInterval(tick);},[]);useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(t)},[toast]);const language=me?.user.language||'en';useEffect(()=>{retryTranslations();document.documentElement.lang=language;document.documentElement.dir=languageList.find(l=>l.code===language)?.rtl?'rtl':'ltr'},[language]);const run=async fn=>{try{return await fn()}catch(e){setToast(e.message);return null}};return <LanguageContext.Provider value={language}><Ctx.Provider value={{me,setMe,reload,boot,catalog,setCatalog,toast:setToast,run,language}}>{children}{toast&&<div className="toast" role="status">{toast}<button onClick={()=>setToast('')}><X size={16}/></button></div>}</Ctx.Provider></LanguageContext.Provider>}
